val content = @Composable {
    Box(modifier = Modifier.fillMaxSize()) {
        Column(
            modifier = Modifier.fillMaxSize().verticalScroll(rememberScrollState()).padding(MonarchTheme.spacing.space4),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
        ) {
            MonarchText(text = {{heading}}, style = MonarchTextStyle.Heading)
            MonarchText(text = {{description}}, style = MonarchTextStyle.Caption)
            rows.forEach { row ->
                MonarchCheckboxRow(
                    checked = row in selected,
                    onCheckedChange = { on -> selected = if (on) selected + row else selected - row },
                    label = row,
                )
            }
        }
        // The launcher hides while the assistant is docked open; on a phone it stays under the sheet.
        if (!(docked && open)) {
            MonarchAiLauncher(
                open = open,
                onOpenChange = { open = it },
                icon = { MonarchIcon(SampleIcons.Bot, contentDescription = null) },
                modifier = Modifier.align(Alignment.BottomEnd).padding(MonarchTheme.spacing.space4),
                variant = MonarchAiLauncherVariant.Subtle,
            )
        }
    }
}
val assistant = @Composable { modifier: Modifier ->
    @OptIn(ExperimentalMonarchApi::class)
    MonarchAiAssistantPanel(
        conversation = conversation,
        title = {{assistant.title}},
        open = open,
        onOpenChange = { open = it },
        modifier = modifier,
        placement = if (docked) MonarchAiAssistantPanelPlacement.Inline else MonarchAiAssistantPanelPlacement.Sheet,
        context = context,
        starters = listOf(
            MonarchAiStarterPrompt("sum", {{assistant.starters.0}}, {{assistant.starters.0}}),
            MonarchAiStarterPrompt("risk", {{assistant.starters.1}}, {{assistant.starters.1}}),
        ),
        onRemoveContext = { id -> if (id == "selection") selected = emptyList() },
        body = selectionBody,
    )
}
Box(modifier = Modifier.fillMaxWidth().height(MonarchTheme.spacing.space24 * 8)) {
    if (docked) {
        @OptIn(ExperimentalMaterial3AdaptiveApi::class)
        val directive = calculatePaneScaffoldDirective(adaptiveInfo)
            .copy(maxHorizontalPartitions = if (open) 2 else 1)
        @OptIn(ExperimentalMaterial3AdaptiveApi::class)
        SupportingPaneScaffold(
            directive = directive,
            value = calculateThreePaneScaffoldValue(
                maxHorizontalPartitions = directive.maxHorizontalPartitions,
                adaptStrategies = SupportingPaneScaffoldDefaults.adaptStrategies(),
                currentDestination = ThreePaneScaffoldDestinationItem<Nothing>(SupportingPaneScaffoldRole.Main),
            ),
            mainPane = { AnimatedPane { content() } },
            supportingPane = { AnimatedPane { assistant(Modifier.fillMaxSize()) } },
        )
    } else {
        content()
        assistant(Modifier)
    }
}

examples.setupTemplate:
val transport = remember {
    object : MonarchAiTransport {
        override fun stream(request: MonarchAiTransportRequest): Flow<MonarchAiStreamEvent> = flowOf(
            MonarchAiStreamEvent.TextDelta("You asked: " + request.messages.lastOrNull()?.text.orEmpty()),
            MonarchAiStreamEvent.Done(),
        )
    }
}
// Hold the conversation above the navigation so it survives moving between screens.
val conversation = rememberMonarchAiConversation(transport)
var open by rememberSaveable { mutableStateOf({{assistant.open}}) }
val rows = listOf({{rows.0}}, {{rows.1}}, {{rows.2}}, {{rows.3}})
var selected by remember { mutableStateOf(listOf<String>()) }
// The page owns the selection; the recipe shows it as a chip and sends it with the next prompt.
val context = listOfNotNull(
    MonarchAiContextItem("page", MonarchAiContextKind.Page, {{assistant.context}}, removable = false, group = "Page"),
    if (selected.isEmpty()) null else MonarchAiContextItem("selection", MonarchAiContextKind.Selection, "${selected.size} rows"),
)
// Sent with each message from the panel; the conversation's own body stays as it is.
val selectionBody = if (selected.isEmpty()) {
    emptyMap()
} else {
    mapOf(
        "selection" to MonarchAiJSON.Array(
            listOf(
                MonarchAiJSON.Object(
                    mapOf(
                        "label" to MonarchAiJSON.Text("Selected"),
                        "text" to MonarchAiJSON.Text(selected.joinToString("; ")),
                    ),
                ),
            ),
        ),
    )
}
val adaptiveInfo = currentWindowAdaptiveInfoV2()
// Docked beside the content from the expanded width class; a sheet on narrower windows.
val docked = adaptiveInfo.windowSizeClass.isWidthAtLeastBreakpoint(WindowSizeClass.WIDTH_DP_EXPANDED_LOWER_BOUND)
// The back gesture closes a docked assistant; the sheet handles back itself.
BackHandler(enabled = docked && open) { open = false }

